import AppKit
import WebKit

extension DesktopRenderTests {
    func run(_ code: String) async throws {
        _ = try await controller.webView.evaluateJavaScript("(() => {\n" + code + "\nreturn true; })()")
    }
    func press(_ title: String, in scope: String = "document") async throws {
        try await run("const scope=\(scope); const button=Array.from(scope.querySelectorAll('button')).find(b=>b.textContent.trim()===\(LibraryManager.quote(title))); if(!button)throw new Error('Button missing: '+\(LibraryManager.quote(title))); button.click();")
    }
    func input(_ selector: String, _ value: String) async throws {
        try await run("const field=document.querySelector(\(LibraryManager.quote(selector))); if(!field)throw new Error('Input missing'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(field,\(LibraryManager.quote(value)));field.dispatchEvent(new Event('input',{bubbles:true}));")
    }
    func verifyLibraryWorkspace() async throws {
        controller.navigate("/library?panel=organize")
        try await wait("document.querySelector('[aria-label=\"Organize Library\"] .settings-cat__create input') !== null")
        try await run("window.__originalReading=null;fetch('/api/v1/backups/document').then(r=>r.json()).then(v=>window.__originalReading=JSON.stringify([v.library,v.progress]));")
        try await wait("window.__originalReading !== null")
        try await input(".settings-cat__create input", "Review Category")
        try await press("New category")
        try await wait("Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Category'))")
        try await run("const row=Array.from(document.querySelectorAll('.settings-cat')).find(e=>e.textContent.includes('Review Category')); row.querySelector('[aria-label=Rename]').click();")
        try await wait("document.querySelector('.settings-modal-input input') !== null")
        try await input(".settings-modal-input input", "Review Renamed")
        try await press("Save", in: "Array.from(document.querySelectorAll('[role=dialog]')).at(-1)")
        try await wait("Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Renamed'))")
        try await run("const rows=Array.from(document.querySelectorAll('.settings-cat'));const row=rows.find(e=>e.textContent.includes('Review Renamed'));window.__categoryIndex=rows.indexOf(row);row.querySelector('[aria-label=\"Move up\"]').click();")
        try await wait("Array.from(document.querySelectorAll('.settings-cat')).findIndex(e=>e.textContent.includes('Review Renamed')) < window.__categoryIndex")
        try await run("Array.from(document.querySelectorAll('.settings-cat')).find(e=>e.textContent.includes('Review Renamed')).querySelector('[aria-label=\"Delete category\"]').click();")
        try await wait("document.querySelector('[aria-label=\"Delete category\"] [class*=footer]') !== null")
        try await press("Delete", in: "Array.from(document.querySelectorAll('[role=dialog]')).at(-1)")
        try await wait("!Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Renamed'))")
        try await press("New filter group")
        try await wait("document.querySelector('input[placeholder=\"Filter group name\"]') !== null")
        try await input("input[placeholder=\"Filter group name\"]", "Review Filter")
        try await press("Save", in: "Array.from(document.querySelectorAll('[role=dialog]')).at(-1)")
        try await wait("Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Filter'))")
        try await run("Array.from(document.querySelectorAll('.settings-cat')).find(e=>e.textContent.includes('Review Filter')).querySelector('[aria-label=\"Edit filter group\"]').click();")
        try await wait("document.querySelector('input[placeholder=\"Filter group name\"]') !== null")
        try await input("input[placeholder=\"Filter group name\"]", "Review Filter Edited")
        try await press("Save", in: "Array.from(document.querySelectorAll('[role=dialog]')).at(-1)")
        try await wait("Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Filter Edited'))")
        try await run("Array.from(document.querySelectorAll('.settings-cat')).find(e=>e.textContent.includes('Review Filter Edited')).querySelector('[aria-label=\"Delete filter group\"]').click();")
        try await wait("document.querySelector('[aria-label=\"Delete filter group\"] [class*=footer]') !== null")
        try await press("Delete", in: "Array.from(document.querySelectorAll('[role=dialog]')).at(-1)")
        try await wait("!Array.from(document.querySelectorAll('.settings-cat__name')).some(e=>e.textContent.includes('Review Filter Edited'))")
        controller.navigate("/library?panel=view")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] [role=combobox]') !== null")
        try await run("document.querySelector('[aria-label=\"Library View Options\"] [role=combobox]').click();")
        try await wait("document.querySelector('[role=listbox]') !== null")
        try await run("Array.from(document.querySelectorAll('[role=option]')).find(e=>e.textContent.trim()==='Uncategorized').click();")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] .select__value').textContent === 'Uncategorized'")
        try await run("const toggle=document.querySelector('[aria-label=\"Library View Options\"] input[type=checkbox]'); if(toggle.checked)toggle.click();")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] input[type=checkbox]').checked === false")
        controller.navigate("/library")
        try await wait("document.querySelector('[role=dialog]') === null")
        controller.navigate("/library?panel=view")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] .select__value')?.textContent === 'Uncategorized' && document.querySelector('[aria-label=\"Library View Options\"] input[type=checkbox]')?.checked === false")
        try await run("window.__savedLibrary=null;fetch('/api/v1/settings').then(r=>r.json()).then(v=>window.__savedLibrary=v.library);")
        try await wait("window.__savedLibrary?.defaultCategory === 'uncategorized' && window.__savedLibrary?.showUncategorized === false")
        try await run("document.querySelector('[aria-label=\"Library View Options\"] [role=combobox]').click();")
        try await wait("document.querySelector('[role=listbox]') !== null")
        try await run("document.querySelector('[role=option]').click();")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] .select__value').textContent !== 'Uncategorized'")
        try await run("document.querySelector('[aria-label=\"Library View Options\"] input[type=checkbox]').click();")
        try await wait("document.querySelector('[aria-label=\"Library View Options\"] input[type=checkbox]').checked")
        try await run("window.__afterReading=null;fetch('/api/v1/backups/document').then(r=>r.json()).then(v=>window.__afterReading=JSON.stringify([v.library,v.progress]));")
        try await wait("window.__afterReading === window.__originalReading")
        controller.navigate("/library")
    }
    func verifyAutomationAndTrackers() async throws {
        controller.navigate("/settings?section=automation")
        try await wait("document.querySelector('[aria-label=\"Automatically refresh source lists\"]') !== null")
        try await run("document.querySelector('[aria-label=\"Automatically refresh source lists\"]').click();")
        try await wait("document.querySelector('[aria-label=\"Automatically refresh source lists\"]').checked === false")
        controller.navigate("/settings?section=general")
        try await wait("location.search === '?section=general'")
        controller.navigate("/settings?section=automation")
        try await wait("document.querySelector('[aria-label=\"Automatically refresh source lists\"]').checked === false && document.querySelector('[aria-label=\"Automatically install source updates\"]').checked === false")
        try await run("window.__policy=null;fetch('/api/v1/source-repos/preferences').then(r=>r.json()).then(v=>window.__policy=v);")
        try await wait("window.__policy?.autoRefreshLists === false && window.__policy?.autoUpdatePackages === false")
        try await run("document.querySelector('[aria-label=\"Automatically refresh source lists\"]').click();")
        try await wait("document.querySelector('[aria-label=\"Automatically refresh source lists\"]').checked")
        try await input("input[aria-label=\"Search settings\"]", "tracker")
        try await wait("document.querySelector('[aria-label=\"Settings search results\"]') !== null")
        try await press("Accounts & Integrations", in: "document.querySelector('[aria-label=\"Settings search results\"]')")
        try await wait("location.search === '?section=accounts'")
        try await run("document.querySelector('[data-settings-group=trackers]').click();")
        try await wait("location.search === '?section=trackers' && document.body.textContent.includes('Fixture User')")
        try await press("Set as default", in: "document.querySelector('.tracker-provider')")
        try await wait("window.__trackerFixture.defaultTracker === 'anilist' && document.querySelector('.tracker-provider button[aria-pressed=true]') !== null")
        controller.navigate("/settings?section=general")
        try await wait("location.search === '?section=general'")
        controller.navigate("/settings?section=trackers&oauth=success")
        try await wait("location.search === '?section=trackers' && document.querySelector('.tracker-provider button[aria-pressed=true]') !== null")
        try await press("Disconnect", in: "document.querySelector('.tracker-provider')")
        try await wait("document.querySelector('[aria-label=\"Disconnect AniList?\"]') !== null")
        try await press("Disconnect", in: "document.querySelector('[aria-label=\"Disconnect AniList?\"]')")
        try await wait("window.__trackerFixture.connected === false && document.querySelector('.tracker-provider').textContent.includes('Not connected')")
        try await run("document.querySelector('[aria-label=\"Unbind AniList\"]').click();")
        try await wait("document.querySelector('[aria-label=\"Remove tracker binding?\"]') !== null")
        try await press("Unbind", in: "document.querySelector('[aria-label=\"Remove tracker binding?\"]')")
        try await wait("window.__trackerFixture.bindings.length === 0")
    }
}
